(* Enable from downstream to upstream *)
Zone3_Run := NOT Zone3_Blocked AND Emergency_Stop AND NOT Fault_State;
Zone2_Run := Zone3_Run AND NOT Zone2_Blocked;
Zone1_Run := Zone2_Run AND NOT Zone1_Blocked;

(* E-Stop kills all zones *)
IF NOT Emergency_Stop OR Fault_State THEN
    Zone1_Run := FALSE;
    Zone2_Run := FALSE;
    Zone3_Run := FALSE;
END_IF;
